adcs_vec3_t s;
adcs_vec3_t miss_vector;
double behind;
double miss;
adcs_status_t status;

if ((position_m == NULL) || (sun_direction == NULL) || (eclipse == NULL) ||
    (behind_m == NULL) || (miss_m == NULL)) {
    if (eclipse != NULL) {
        *eclipse = 0;
    }
    if (behind_m != NULL) {
        *behind_m = 0.0;
    }
    if (miss_m != NULL) {
        *miss_m = INFINITY;
    }
    return ADCS_E_NULL;
}

*eclipse = 0;
*behind_m = 0.0;
*miss_m = INFINITY;

if ((!adcs_is_finite_vec3(position_m)) || (!adcs_is_finite_vec3(sun_direction)) ||
    (!isfinite(earth_radius_m)) || (earth_radius_m <= 0.0)) {
    return ADCS_E_RANGE;
}

status = adcs_vec3_normalize(sun_direction, ADCS_EPS_NORM, &s);
if (status != ADCS_OK) {
    return ADCS_E_RANGE;
}

behind = -adcs_vec3_dot(position_m, &s);
miss_vector = adcs_vec3_add(position_m, &adcs_vec3_scale(&s, behind));
miss = adcs_vec3_norm(&miss_vector);

*eclipse = (behind > 0.0) && (miss < earth_radius_m);
*behind_m = behind;
*miss_m = miss;

return ADCS_OK;

